10	/// Given a path (absolute or relative) to a resource file, returns the
11	/// relative path from the bundle resources directory where that resource
12	/// should be stored.
13	pub fn resource_relpath(path: &Path) -> PathBuf {
14	  let mut dest = PathBuf::new();
15	  for component in path.components() {
16	    match component {
17	      Component::Prefix(_) => {}
18	      Component::RootDir => dest.push("_root_"),
19	      Component::CurDir => {}
20	      Component::ParentDir => dest.push("_up_"),
21	      Component::Normal(string) => dest.push(string),
22	    }
23	  }
24	  dest
25	}
